import React, { useCallback, useEffect, useState } from 'react';
import { useInAppNavigate } from '@/utils/useInAppNavigate';
import {
  Button,
  FormActions,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Title, Text, Spin, Popconfirm } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import type { ExpansionSimulationDto } from '../../../services/fpc/types';
import styles from './ExpansionSimList.module.css';

const TEST_ID = 'expansion-sim-list';

const fVnd = (v?: number | null): string => {
  if (v == null) return '—';
  return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);
};

const ExpansionSimList: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useInAppNavigate();
  const { canViewExpansionSimulator, canRunExpansionSimulator } = useFpcPermissions();

  const [items, setItems] = useState<ExpansionSimulationDto[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const list = await fpcService.getExpansionSimList();
      setItems(list ?? []);
    } catch {
      setItems([]);
      dispatchAppToast(dispatch, { message: 'Không thể tải danh sách mô phỏng mở rộng', type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = window.setTimeout(() => { void fetchList(); }, 0);
    return () => window.clearTimeout(t);
  }, [fetchList]);

  const handleDelete = async (id: string) => {
    try {
      await fpcService.deleteExpansionSim(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa mô phỏng mở rộng', type: 'success' });
      void fetchList();
    } catch {
      dispatchAppToast(dispatch, { message: 'Không xóa được mô phỏng', type: 'error' });
    }
  };

  if (!canViewExpansionSimulator) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.empty}>
          <Text type="secondary">Bạn không có quyền xem mô phỏng mở rộng.</Text>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>
              <i className="fas fa-store" style={{ marginRight: 8, color: '#2563eb' }} />
              Mô phỏng mở rộng chi nhánh
            </Title>
            <Text type="secondary">
              Chứng từ tạo kịch bản mở điểm mới · CAPEX · hòa vốn · hoàn vốn
            </Text>
          </div>
          <FormActions align="end">
            <Button onClick={() => void fetchList()} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            <Button
              variant="secondary"
              onClick={() => navigate('/tc/kh/kich-ban')}
              data-testid={`${TEST_ID}-scenario-btn`}
            >
              <i className="fas fa-cubes" /> Kịch bản
            </Button>
            {canRunExpansionSimulator && (
              <Button
                variant="primary"
                onClick={() => navigate('/tc/kh/mo-rong-ch/new')}
                data-testid={`${TEST_ID}-create-btn`}
              >
                <i className="fas fa-plus" /> Tạo mới
              </Button>
            )}
          </FormActions>
        </div>
      </div>

      {loading ? (
        <div className={styles.empty}>
          <Spin />
          <Text type="secondary">Đang tải…</Text>
        </div>
      ) : (
        <div className={styles.tableWrapper}>
          <table className={styles.table} data-testid={`${TEST_ID}-table`}>
            <thead>
              <tr>
                <th>Tên mô phỏng</th>
                <th>Trạng thái</th>
                <th>Tổng đầu tư</th>
                <th>Hòa vốn</th>
                <th>Hoàn vốn</th>
                <th>DT thuần/tháng</th>
                <th>Khuyến nghị</th>
                <th>Thao tác</th>
              </tr>
            </thead>
            <tbody>
              {items.length === 0 ? (
                <tr>
                  <td colSpan={8}>
                    <Text type="secondary">Chưa có chứng từ. Bấm Tạo mới để lập mô phỏng.</Text>
                  </td>
                </tr>
              ) : (
                items.map(row => (
                  <tr key={row.id}>
                    <td style={{ fontWeight: 500 }}>{row.name}</td>
                    <td className={styles.colCenter}>{row.status || '—'}</td>
                    <td className={styles.colRight}>{fVnd(row.totalInvestment)}</td>
                    <td className={styles.colCenter}>
                      {row.breakEvenMonth != null ? `${row.breakEvenMonth} tháng` : '—'}
                    </td>
                    <td className={styles.colCenter}>
                      {row.paybackMonths != null ? `${row.paybackMonths} tháng` : '—'}
                    </td>
                    <td className={styles.colRight}>{fVnd(row.monthlyNetCashflow)}</td>
                    <td>{row.recommendation || '—'}</td>
                    <td className={styles.colCenter}>
                      <FormActions align="center">
                        <Button
                          variant="secondary"
                          onClick={() => navigate(`/tc/kh/mo-rong-ch/${row.id}`)}
                          data-testid={`${TEST_ID}-open-${row.id}`}
                        >
                          Mở
                        </Button>
                        {canRunExpansionSimulator && (
                          <Popconfirm
                            title="Xóa mô phỏng này?"
                            onConfirm={() => void handleDelete(row.id)}
                          >
                            <Button data-testid={`${TEST_ID}-delete-${row.id}`}>Xóa</Button>
                          </Popconfirm>
                        )}
                      </FormActions>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default ExpansionSimList;
